{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "SDI enable setting",
      "Unit": "neorv32_sdi",
      "Information": "The enable setting controls whether the SDI FIFOs are cleared and whether serial processing is enabled; the IP behavior depends on it. It is written through the bus control access and can be read back.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because an unchecked bus write changes the setting at line 133; availability is at risk because the setting clears both FIFOs at lines 200 and 239 and controls serial state at line 296.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker issuing a control-register write could disable the interface, clear queued data, or prevent serial transfers.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        117,
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Transmitted serial payload",
      "Unit": "neorv32_sdi",
      "Information": "The payload written by the bus is queued for transmission and shifted onto the SDI data output. The serial transmit function depends on preserving and delivering this payload.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because the payload reaches the observable serial output at line 345; integrity is at risk because bus data is loaded into the transmit path at line 201 and shifted through the serial register at lines 305 and 327; availability is at risk because disabling the interface clears the transmit FIFO at line 200 and sampled chip select controls whether transmission starts at line 307.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could alter a bus write, clear the transmit queue, or prevent the selected payload from being transmitted.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Received serial payload",
      "Unit": "neorv32_sdi",
      "Information": "The payload sampled from the SDI data input is assembled into a serial word, buffered, and returned to the bus. The receive function depends on capturing and making the received word available for software.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because the received payload can be exposed through the bus response at line 162; integrity is at risk because sampled input data enters at line 270 and is assembled by serial-register updates at line 327; availability is at risk because receive data can be discarded when the receive FIFO is cleared at line 239 or when chip select terminates the transfer at line 324.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could alter sampled serial bits, clear the receive buffer, or terminate reception before the word is returned.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Serial chip-select handshake",
      "Unit": "neorv32_sdi",
      "Information": "The chip-select handshake frames SDI transfers and determines whether serial reception or transmission starts, continues, or terminates. It enters through sdi_csn_i and is consumed by the unit without a corresponding output port.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Availability is at risk because the sampled chip-select controls transfer start at line 307 and causes the serial engine to leave its transfer states at lines 315 and 324.",
      "Objectives At Risk": [
        "A"
      ],
      "Attack": "An attacker could hold or toggle chip select to prevent a transfer or truncate it before completion.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        269
      ],
      "Held Lines": [],
      "Exit Lines": []
    },
    {
      "Concept ID": "C5",
      "Concept Name": "SDI interrupt notification",
      "Unit": "neorv32_sdi",
      "Information": "The interrupt notification reports selected receive or transmit FIFO conditions to the surrounding system. The IP or its software service path depends on this notification to respond to pending serial activity.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because the notification is produced by the internal condition logic at line 249 and can therefore be asserted or suppressed incorrectly; availability is at risk because reset and the same condition logic can withhold the interrupt at lines 247 and 249.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could cause false interrupt indications or suppress the notification so pending receive or transmit work is not serviced.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        247,
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt-enable settings",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "These bus-written settings only tune the interrupt-request output, so the Port options rule bars them as concepts of their own; their use is in the interrupt expression at lines 249 through 254."
    },
    {
      "Candidate Name": "SDI serial clock",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The serial clock input only paces sampling and state advancement at lines 268, 317, and 326, so the Clocks and resets rule excludes it as a conceptual asset."
    },
    {
      "Candidate Name": "Clock and reset distribution",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "clk_i and rstn_i only time or reset internal logic and FIFO instances at lines 115, 123, 184, 185, 219, and 220, so the Clocks and resets rule excludes them."
    },
    {
      "Candidate Name": "Bus access command",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The request strobe, direction, and address only select register or FIFO accesses and generate their strobes at lines 130 through 142, 202, and 240, so Access command fields and Forwarded transactions bar them as separate concepts."
    },
    {
      "Candidate Name": "Bus response handshake and error",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge repeats the request strobe and the error is tied to a constant at lines 125 and 126, so Bus handshake copies bars them as information of their own."
    },
    {
      "Candidate Name": "FIFO occupancy status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The FIFO availability, half-full, free, and empty indications only report or time buffered data and are returned or used in interrupt generation at lines 153 through 158 and 250 through 254, so Buffer and engine status bits bars a separate concept."
    },
    {
      "Candidate Name": "Serial sequencing state and pacing",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The serial state, count, start, done, and synchronizer stages only order or pace the serial payload transfer in the state machine at lines 297 through 340, so Sequencing state, Pacing pulses, and Working values exclude them."
    },
    {
      "Candidate Name": "FIFO depth configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO fixes FIFO depth at build time through the generic and instance maps at lines 20, 176, and 211, so Build-time values excludes it from runtime conceptual assets."
    }
  ],
  "Notes": []
}
